"use strict";function showNotificationToast(n){const i=document.getElementById("toast-container")||createToastContainer(),t="toast-"+Date.now(),r=`
        <div id="${t}" class="toast align-items-center text-white bg-primary border-0" role="alert" aria-live="assertive" aria-atomic="true">
          <div class="d-flex">
            <div class="toast-body">
              🔔 ${n}
            </div>
            <button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast" aria-label="Close"></button>
          </div>
        </div>
    `;i.insertAdjacentHTML("beforeend",r);const u=document.getElementById(t),f=new bootstrap.Toast(u,{delay:5e3});f.show()}function createToastContainer(){const n=document.createElement("div");return n.id="toast-container",n.className="toast-container position-fixed bottom-0 end-0 p-3",n.style.zIndex="1055",document.body.appendChild(n),n}const connection=(new signalR.HubConnectionBuilder).withUrl("/notificationHub").configureLogging(signalR.LogLevel.Information).build();connection.on("ReceiveNotification",function(n){showNotificationToast(n)});connection.start().then(function(){console.log("SignalR підключено.")}).catch(function(n){return console.error(n.toString())});